function escHtml(str) { return String(str||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }

// ════════════════════════════════════════════════════════════
//  Heatmap popup
// ════════════════════════════════════════════════════════════

async function openTargetHeatmap(greenhouse, targetName) {
    const overlay = document.createElement("div"); overlay.className = "hmv-overlay";
    const modal   = document.createElement("div"); modal.className   = "hmv-modal";
    overlay.appendChild(modal); document.body.appendChild(overlay);
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    document.addEventListener("keydown", function onEsc(e) {
        if (e.key === "Escape") { overlay.remove(); document.removeEventListener("keydown", onEsc); }
    });

    const header = document.createElement("div"); header.className = "hmv-header";
    header.innerHTML = `<div class="hmv-header-left"><span class="hmv-gh-label">${greenhouse}</span><span class="hmv-arrow">›</span><span class="hmv-target-label">${targetName}</span></div><div class="hmv-header-right"><span class="hmv-date-badge" id="hmv-date-badge">Loading…</span><button class="hmv-close" title="Close (Esc)">&times;</button></div>`;
    header.querySelector(".hmv-close").addEventListener("click", () => overlay.remove());
    modal.appendChild(header);

    const body = document.createElement("div"); body.className = "hmv-body";
    body.innerHTML = `<div class="hmv-loading"><div class="hmv-spinner"></div><p>Loading scouting data…</p></div>`;
    modal.appendChild(body);

    let data;
    try {
        if (_scoutingCache[greenhouse]) { data = _scoutingCache[greenhouse]; }
        else {
            const r = await frappe.call({ method: "upande_scp.serverscripts.get_scouting_report.getScoutingData", args: { greenhouse } });
            data = r.message || r.data;
            if (data && data.scouting_entries && data.scouting_entries.length) _scoutingCache[greenhouse] = data;
        }
    } catch (err) { body.innerHTML = `<div class="hmv-error">Failed to load scouting data: ${err.message || err}</div>`; return; }

    if (!data || !data.scouting_entries || !data.scouting_entries.length) {
        body.innerHTML = `<div class="hmv-error">No scouting data found for <strong>${greenhouse}</strong>.</div>`; return;
    }

    const dateBadge = document.getElementById("hmv-date-badge");
    if (dateBadge && data.scouting_date) dateBadge.textContent = `Scouting: ${new Date(data.scouting_date).toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"})}`;

    body.innerHTML = "";
    const entries  = data.scouting_entries || [];
    const bedNum   = s => { const m = String(s).match(/Bed (\d+)/);  return m ? +m[1] : null; };
    const zoneNum  = s => { if (typeof s === "number") return s; const m = String(s).match(/Zone (\d+)/); return m ? +m[1] : null; };
    const obsTypes = [];
    entries.forEach(e => { Object.keys(e).forEach(k => { if (k.endsWith("_scouting_entry") && !obsTypes.includes(k)) obsTypes.push(k); }); });

    let obsColor = "#6b7280", obsSymbol = "", maxBed = 0, maxZone = 0;
    const matrix = {};
    entries.forEach(e => {
        const bed = bedNum(e.bed), zone = zoneNum(e.zone); if (!bed || !zone) return;
        if (bed > maxBed) maxBed = bed; if (zone > maxZone) maxZone = zone;
        obsTypes.forEach(t => {
            (e[t] || []).forEach(obs => {
                if (obs.name !== targetName) return;
                obsColor  = obs.color  || obsColor;
                obsSymbol = obs.symbol || obsSymbol;
                if (!matrix[bed])       matrix[bed]       = {};
                if (!matrix[bed][zone]) matrix[bed][zone] = { count: 0, symbol: obsSymbol };
                matrix[bed][zone].count += (obs.count || 1);
            });
        });
    });

    let maxCount = 0, total = 0;
    Object.values(matrix).forEach(row => Object.values(row).forEach(c => { total += c.count; maxCount = Math.max(maxCount, c.count); }));

    if (maxCount === 0) {
        body.innerHTML = `<div class="hmv-no-data"><div class="hmv-no-data-icon">🔍</div><p><strong>${targetName}</strong> was not observed in <strong>${greenhouse}</strong>.</p></div>`;
        return;
    }

    const bedNumbering  = data.custom_bed_numbering  || "Top to Bottom";
    const zoneNumbering = data.custom_zone_numbering || "Right to Left";
    const bedRange  = bedNumbering  === "Top to Bottom" ? Array.from({length:maxBed}, (_,i)=>maxBed-i)  : Array.from({length:maxBed}, (_,i)=>i+1);
    const zoneRange = zoneNumbering === "Right to Left" ? Array.from({length:maxZone},(_,i)=>maxZone-i) : Array.from({length:maxZone},(_,i)=>i+1);

    const statsBar = document.createElement("div"); statsBar.className = "hmv-stats-bar";
    statsBar.innerHTML = `<div class="hmv-stat"><span class="hmv-stat-label">Total Count</span><span class="hmv-stat-val">${total}</span></div><div class="hmv-stat"><span class="hmv-stat-label">Max / Zone</span><span class="hmv-stat-val">${maxCount}</span></div><div class="hmv-stat"><span class="hmv-stat-label">Beds Affected</span><span class="hmv-stat-val">${Object.keys(matrix).length}</span></div><div class="hmv-stat"><span class="hmv-stat-label">Zones Affected</span><span class="hmv-stat-val">${Object.values(matrix).reduce((s,r)=>s+Object.keys(r).length,0)}</span></div><div class="hmv-intensity-legend"><span>None</span><span class="hmv-leg-box" style="background:#e5e7eb"></span><span class="hmv-leg-box" style="background:${obsColor};opacity:.2"></span><span class="hmv-leg-box" style="background:${obsColor};opacity:.4"></span><span class="hmv-leg-box" style="background:${obsColor};opacity:.6"></span><span class="hmv-leg-box" style="background:${obsColor};opacity:.8"></span><span class="hmv-leg-box" style="background:${obsColor};opacity:1"></span><span>High</span></div>`;
    body.appendChild(statsBar);

    const gridWrap = document.createElement("div"); gridWrap.className = "hmv-grid-wrap";
    const gridEl   = document.createElement("div"); gridEl.className   = "hmv-grid"; gridEl.style.gridTemplateColumns = `36px repeat(${maxZone}, 1fr)`;
    const intensityClass = cnt => { if (!cnt) return "hmv-i0"; const r=cnt/maxCount; if(r<=.2)return"hmv-i1"; if(r<=.4)return"hmv-i2"; if(r<=.6)return"hmv-i3"; if(r<=.8)return"hmv-i4"; return"hmv-i5"; };

    const corner = document.createElement("div"); corner.className = "hmv-corner"; gridEl.appendChild(corner);
    zoneRange.forEach(z => { const lbl=document.createElement("div"); lbl.className="hmv-zlbl"; lbl.textContent=z; gridEl.appendChild(lbl); });
    bedRange.forEach(bed => {
        const bLbl = document.createElement("div"); bLbl.className="hmv-blbl"; bLbl.textContent=bed; gridEl.appendChild(bLbl);
        zoneRange.forEach(zone => {
            const cell=matrix[bed]&&matrix[bed][zone]?matrix[bed][zone]:null, cnt=cell?cell.count:0;
            const el=document.createElement("div"); el.className=`hmv-cell ${intensityClass(cnt)}`; if(cnt>0) el.style.backgroundColor=obsColor;
            const tip=document.createElement("div"); tip.className="hmv-tip";
            tip.innerHTML=cnt>0?`<strong>B${bed} · Z${zone}</strong><br>${targetName}: <strong>${cnt}</strong>${cell.symbol?" "+cell.symbol:""}`:`<strong>B${bed} · Z${zone}</strong><br>None`;
            el.appendChild(tip);
            el.addEventListener("mouseenter", () => {
                const r=el.getBoundingClientRect(); tip.style.top="100%"; tip.style.bottom="auto"; tip.style.marginTop="4px";
                if(r.left<window.innerWidth/3){tip.style.left="0";tip.style.right="auto";tip.style.transform="";}
                else if(r.right>window.innerWidth*2/3){tip.style.right="0";tip.style.left="auto";tip.style.transform="";}
                else{tip.style.left="50%";tip.style.right="auto";tip.style.transform="translateX(-50%)";}
            });
            gridEl.appendChild(el);
        });
    });
    gridWrap.appendChild(gridEl); body.appendChild(gridWrap);
}

